// Original teaching notes: view-specific pitfalls, with age-appropriate overrides.
const tips={
 head:[['사단면·단축 주의','두개골이 비대칭이거나 소뇌가 들어오면 TTP 높이와 기울임을 다시 맞춥니다. 비스듬한 타원에 HC를 맞추지 않습니다.'],['골화 음영·게인','근위 두개골 음영을 게인만 올려 해결하려 하지 말고 접근 창을 옮깁니다. 뼈 경계가 번지지 않게 조절합니다.'],['캘리퍼 방식 일치','BPD는 사용한 성장곡선의 측정 방식과 맞추고 HC는 두개골 바깥 윤곽을 따릅니다.'] ],
 ventricle:[['측정 축 주의','심방 폭은 맥락총 사구 높이에서 뇌실 장축에 수직으로 잽니다. 비스듬한 내벽 간 거리를 사용하지 않습니다.'],['근위 반구 음영','가려진 뇌실을 정상으로 간주하지 말고 반대쪽 접근으로 보완합니다. 선명한 원위 뇌실도 정확한 높이를 먼저 확인합니다.'],['경계·확대','벽을 구분할 수 있는 확대에서 내벽–내벽으로 측정합니다. 과한 게인으로 벽이 두꺼워 보이지 않도록 합니다.']],
 earlybrain:[['나비 모양 구분','1분기의 밝은 나비 모양 맥락총을 양측 시상으로 오인하지 않습니다. 인접 높이를 스윕해 구분합니다.'],['대칭 확인','한쪽 맥락총이 작아 보이면 사선 단면과 근위 음영을 먼저 교정합니다.'],['해상도 한계','디지털 확대만으로 작은 구조가 선명해지지는 않습니다. 주수와 해상도에 맞춰 관찰 가능 여부를 기록합니다.']],
 cerebellum:[['과도한 틸트 주의','CSP·시상 등 기준 표지가 사라지고 안와나 두개기저부가 들어오면 기울임을 줄여 TCP를 다시 맞춥니다. 사선 단면이나 불명확한 후두골 경계에서 NF를 측정하지 않습니다.'],['음향 음영 극복 · Shadowing','후두골 음영으로 소뇌·뼈 외측 경계가 가려지면 탐촉자 위치와 입사 방향을 조금씩 바꿉니다. 특정 태아 자세를 정답으로 정하지 말고 필요시 산모 체위 변경·시간차 재관찰로 음향창을 확보합니다.'],['프로브 압박·NF 경계','과한 압박으로 영상을 억지로 얻지 말고 접촉을 편안하게 유지합니다. NF를 평가할 때는 목 자세와 피부·후두골 외측 경계가 명확한지 확인합니다. 압박만으로 수치 변화 방향을 단정하지 않습니다.']],
 face:[['입술 가성 결손','비스듬한 관상면·음영으로 상순이 끊겨 보이면 작은 좌우 스윕으로 연속성을 재확인합니다.'],['가림 구조','손·제대·자궁벽이 얼굴을 가리면 강하게 누르기보다 접근 창과 관찰 시점을 바꿉니다.'],['평가 범위','상순이 연속되어도 구개 전체를 확인한 것은 아닙니다. 의심 소견은 추가 단면으로 평가합니다.']],
 orbit:[['한쪽 안와만 보일 때','두 안와가 같은 높이에 들어오도록 머리 회전과 단면 기울임을 교정합니다.'],['수정체 확인','안와 뼈 음영과 실제 수정체(Lens)를 구분하도록 짧게 스윕하고 게인을 조절합니다.'],['거리 측정','주수별 참고치와 같은 단면·캘리퍼 정의를 사용합니다. 사선으로 늘어난 안와 간 거리를 재지 않습니다.']],
 facialprofile:[['정중면 확인','턱이 작거나 코가 평평해 보이면 먼저 방시상면이 아닌지 확인합니다.'],['겹침·음영','손과 제대를 코·입술 윤곽으로 오인하지 않도록 인접 프레임에서 분리합니다.'],['얼굴 자세','목이 과굴곡된 상태의 턱 관계를 그대로 판정하지 말고 중립에 가까운 자세에서 다시 관찰합니다.']],
 heart:[['중격 가성 결손 · Dropout','빔과 중격이 나란하면 중격 일부가 사라져 보일 수 있습니다. 다른 입사 방향과 인접 면에서 확인합니다.'],['프레임 속도','심장 프리셋과 좁은 영상 폭으로 판막 움직임을 확인하고 cine를 저장합니다.'],['압박·태동','태동으로 기울어진 한 프레임만 택하지 말고 안정된 연속 영상에서 사강면과 심장 주기를 확인합니다.']],
 lvot:[['연결 확인','대동맥이 심실중격과 이어지는지 스윕으로 추적합니다. 혈관 단면 하나만으로 좌심실 기시를 판단하지 않습니다.'],['중격·혈관벽 음영','입사각 때문에 생긴 끊김은 다른 각도로 재확인합니다.'],['도플러 번짐','색이 벽 밖으로 번지면 게인을 낮추고 회색조와 비교합니다. 판막 개폐는 cine로 확인합니다.']],
 rvot:[['혈관 혼동','우심실에서 주폐동맥·분지까지 따라가 대동맥과 구별합니다.'],['분지 절단','한 분지가 안 보이면 단면에서 벗어났는지 작은 스윕으로 확인합니다.'],['판막 주기','수축기의 판막 개방과 이완기의 폐쇄를 정지 화면 모양만으로 구분하지 않습니다.']],
 threevpa:[['측정 부위 혼동','주폐동맥 직경과 폐동맥판륜을 혼용하지 않습니다. 참고치가 정의한 부위를 먼저 확인합니다.'],['사선 직경','혈관 장축에 수직인 직경을 확보하고 벽이 흐린 프레임은 측정에서 제외합니다.'],['주기·색 번짐','참고치와 같은 심장 주기·캘리퍼 방식으로 재며 색 도플러의 번진 외곽을 혈관벽으로 잡지 않습니다.']],
 threev:[['3VT와 구별','3VV의 PA·Ao·SVC 배열을 확인합니다. 더 위쪽 궁의 합류 단면과 섞어 해석하지 않습니다.'],['크기 비교','같은 적절한 횡단면에서 비교합니다. 사선으로 잘린 혈관의 긴 축을 직경으로 비교하지 않습니다.'],['혈관 수만 세지 않기','세 개가 보인다는 이유만으로 끝내지 않고 위치·크기·연결을 확인합니다.']],
 vessels:[['3VV와 구별','3VT에서는 기관(Trachea)과 두 궁의 합류 관계까지 확인합니다. 혈관 세 개만 보이는 면으로 대신하지 않습니다.'],['V자 가성 연속','색 번짐이 두 혈관을 연결해 보이게 할 수 있으므로 회색조와 연속 스윕을 함께 확인합니다.'],['좌우 기준','화면 좌우를 태아 좌우로 간주하지 말고 태위와 기관 기준으로 궁의 위치를 판단합니다.']],
 aoarch:[['동맥관궁 혼동','상행대동맥의 기시와 목 혈관 분지를 추적해 대동맥궁임을 확인합니다.'],['궁 단축','협부가 짧거나 끊겨 보이면 궁의 곡선을 따라 작은 스윕으로 재정렬합니다.'],['색상 해석','도플러 빨강·파랑은 탐촉자에 대한 흐름 방향입니다. 색만으로 동맥 종류를 정하지 않습니다.']],
 ductarch:[['대동맥궁 혼동','우심실–주폐동맥–동맥관 연결을 추적합니다. 궁의 곡선 모양만으로 이름을 붙이지 않습니다.'],['연결 누락','3VT의 V자 화면이 동맥관궁 종단면을 대신하지 않습니다. 하행대동맥까지 이어지는지 확인합니다.'],['협착 오인','비스듬한 절단과 색 설정을 먼저 교정합니다. 색 영상 하나만으로 협착을 판정하지 않습니다.']],
 bicaval:[['대동맥과 구별','각 혈관을 우심방까지 추적하여 상대·하대정맥 연결을 확인합니다.'],['한쪽만 보이는 면','두 정맥이 동시에 안 보이면 방시상면을 미세 이동하고 각각의 연결도 저장합니다.'],['저속 혈류','정맥 혈류에 맞는 도플러 설정을 사용하며 색이 안 보인다는 이유만으로 혈관 부재를 판단하지 않습니다.']],
 abdomen:[['비원형 단면','길쭉한 복부와 비대칭 늑골은 사선 여부를 점검합니다. 몸통 축에 수직으로 다시 맞춥니다.'],['잘못된 높이','AC 면은 위·문맥동을 확인하고 심장이나 신장이 들어오는 높이를 피합니다.'],['압박·윤곽','복부 형태가 변할 정도로 누르지 않고 피부 외곽을 따라 계측합니다. 호흡운동·태동이 적은 프레임을 고릅니다.']],
 cord:[['삽입부 혼동','자유 제대 고리와 태반 부착부를 태아 복벽 삽입부로 오인하지 않습니다.'],['제대 음영','제대 뒤 음영으로 복벽이 끊겨 보이면 다른 입사 방향으로 실제 연결을 확인합니다.'],['색 번짐','색 도플러로 혈관을 보완하되 번진 색이 복벽 경계를 덮지 않게 조절합니다.']],
 diaphragm:[['한쪽만 확인하지 않기','좌우 반횡격막을 각각 추적합니다. 한쪽 곡선만으로 양측을 평가하지 않습니다.'],['가성 끊김','늑골 음영과 단면 이탈에 의한 끊김을 인접 시상·관상 스윕으로 확인합니다.'],['장기 위치 병행','얇은 선만 찾지 말고 위·간과 흉강 장기의 위치를 함께 평가합니다.']],
 kidneys:[['신우 사선 측정','신우 전후경은 적절한 신장 횡단면의 내측 경계 사이를 잽니다. 가장 길게 보이는 대각선으로 재지 않습니다.'],['양측 확인','근위 신장 음영은 다른 창에서 보완합니다. 한쪽만 선명한 영상을 양측 정상으로 기록하지 않습니다.'],['낭성 구조 구분','수질 피라미드와 신우를 종단·관상면으로 구별하고 방광·양수와 함께 봅니다.']],
 kidneysag:[['장축 단축','양극이 모두 보이는지 확인하고 상·하극이 잘린 길이를 기록하지 않습니다.'],['신우 계측면','종단면 신우의 긴 길이를 횡단 전후경과 혼용하지 않습니다.'],['좌우 표시','양쪽 신장을 따로 추적·표시하여 같은 신장을 두 번 저장하지 않도록 합니다.']],
 kidneycor:[['겹친 장기','부신을 신장 상극으로 오인하지 않도록 양극과 신우 위치를 함께 확인합니다.'],['몸통 굴곡','두 신장이 한 면에 안 들어오면 각각 저장하고 동시 관찰의 한계를 남깁니다.'],['다른 면으로 보완','관상면의 존재 확인만으로 내부 구조 평가를 끝내지 않고 횡단·종단면을 추가합니다.']],
 pelvis:[['빈 방광','방광이 안 보이면 충만을 기다려 재관찰합니다. 한 프레임으로 부재를 판단하지 않습니다.'],['다른 낭성 구조','골반 정중선과 제대동맥 관계를 확인하여 장·다른 낭성 구조와 구별합니다.'],['색 번짐','방광 옆 제대동맥을 볼 때 색이 방광 내부를 덮지 않게 조절합니다.']],
 spine:[['음영과 결손 구분','뼈 음영으로 끊겨 보이면 다른 방향의 횡단·시상·관상면에서 재확인합니다.'],['피부 누락','골화 중심뿐 아니라 등 피부의 연속성과 요천추 끝을 확인합니다.'],['구간 누락','굴곡된 척추를 구간별로 겹치게 저장하고 머리부터 천골까지 빠진 높이가 없는지 확인합니다.']],
 femur:[['단축 오차','양끝이 보이는 골화된 골간의 최장축을 확보합니다. 비스듬히 잘린 길이를 사용하지 않습니다.'],['끝점 선택','골간 길이에 원위 골단을 포함하지 않습니다.'],['좌우 혼동','골반부터 무릎까지 추적하여 대퇴골임을 확인하고 측면을 표시합니다.']],
 tibia:[['두 뼈 분리','경골과 비골을 무릎에서 발목까지 각각 추적합니다. 겹쳐 보이면 회전·스윕을 조절합니다.'],['단축·음영','양끝이 선명하지 않으면 길이 차이를 단정하지 말고 다른 창에서 봅니다.'],['발과의 관계','뼈 두 개만 확인하지 말고 발목·발 방향을 움직임과 함께 관찰합니다.']],
 foot:[['자세성 변형','자궁벽에 눌린 일시적인 발 자세를 고정 변형으로 단정하지 않습니다.'],['종아리 연결','발바닥 모양만 보지 말고 경골·비골과 발목의 관계를 여러 면에서 확인합니다.'],['발가락 가림','겹침·음영·태동으로 보이지 않는 발가락을 결손으로 판단하지 말고 재관찰합니다.']],
 humerus:[['뼈 식별','어깨에서 팔꿈치까지 연결을 추적해 상완골을 다른 장골과 구별합니다.'],['단축 오차','골간의 양끝이 한 면에 들어오도록 회전하고 짧게 잘린 면을 피합니다.'],['양측 기록','몸통 앞에 겹친 팔은 각각 추적해 좌우를 구분합니다.']],
 forearm:[['요골·척골 겹침','팔꿈치–손목을 따라 두 뼈를 개별 추적하며 겹침이 풀리는 면으로 회전합니다.'],['그림자 결손','한 뼈가 안 보일 때 입사 방향과 음영을 먼저 확인합니다.'],['손목 관계','길이만 비교하지 말고 손목과 손의 방향·움직임을 함께 확인합니다.']],
 hand:[['주먹 쥔 자세','한 번의 닫힌 손으로 손가락 모양을 판정하지 않고 펴지는 움직임을 기다립니다.'],['겹침과 가림','얼굴·제대에 겹친 손은 별도로 추적합니다. 보이지 않는 손가락을 없다고 기록하지 않습니다.'],['손목 연결','전완에서 손목으로 이어지는 방향과 양측 손을 구별해 저장합니다.']],
 genitalia:[['단면·주수','주수에 맞는 관찰 표지를 사용하고 불분명한 단면으로 성별을 단정하지 않습니다.'],['제대 혼동','다리 사이 제대를 외부생식기로 오인하지 않도록 연속 스윕으로 분리합니다.'],['다리 겹침','허벅지가 밀착해 가려지면 과한 압박 대신 다른 창이나 시점에서 재관찰합니다.']],
 placenta:[['위치 판단','태반만 크게 보지 말고 하부 자궁·내자궁구와의 관계를 함께 확인합니다.'],['방광·수축 영향','방광 팽창이나 일시적 자궁 수축으로 하부 자궁 모양이 달라지면 조건을 교정한 뒤 재평가합니다.'],['경계·혈관 구분','태반 실질 가장자리와 주변 혈관을 구분합니다. 저위 태반이 의심되면 적응증에 따른 경질초음파로 확인합니다.']],
 cervix:[['압박으로 인한 연장','경질 탐촉자 압박은 경부를 인위적으로 길게 보이게 할 수 있습니다. 힘을 줄이고 앞뒤 경부 입술이 균형적인지 확인합니다.'],['방광·가성 내구','방광을 비우고 하부 자궁을 경부로 잘못 포함하지 않도록 내구·외구·경관을 모두 확인합니다.'],['동적 변화','충분히 관찰하여 기술적으로 적절한 최단 길이를 기록합니다. 불완전한 경계의 짧은 값은 채택하지 않습니다.']],
 profile:[['굴곡·과신전','CRL은 중립 자세의 정중시상면에서 측정합니다. 굽힌 몸을 대각선으로 재지 않습니다.'],['끝점 선택','머리끝과 엉덩이끝에 캘리퍼를 놓고 팔다리·난황낭을 제외합니다.'],['확대 범위','두 끝점이 모두 선명하도록 확대하되 화면 밖으로 잘리지 않게 합니다.']],
 nt:[['목 자세','과굴곡·과신전은 NT에 영향을 줄 수 있으므로 중립 자세를 확보합니다.'],['피부·양막 구분','양막을 피부 경계로 잡지 않도록 태동과 인접 프레임에서 분리합니다.'],['경계와 게인','과한 게인으로 투명 공간을 좁히지 않도록 조절하고 정중시상면의 가장 넓은 NT에서 내측 경계에 캘리퍼를 놓습니다.']]
};
const ageNotes={
 spine:['초기 골화 중심과 등 피부를 함께 확인하고 작은 구조의 관찰 한계를 기록합니다.','요천추와 뒤쪽 피부를 놓치지 않도록 전체 척추를 여러 면에서 확인합니다.','굴곡된 척추를 구간별로 겹치게 저장하고 음영 때문에 빠진 높이를 확인합니다.'],
 genitalia:['생식결절은 주수와 태아 자세의 영향을 받습니다. 불확실한 성별을 단정하지 않습니다.','다리 사이 제대와 외부생식기를 구별하고 단면·영상의 충분성을 확인합니다.','허벅지 겹침과 태위로 가려질 수 있습니다. 관찰이 제한되면 이를 명시합니다.'],
 brain:['초기에는 CSP와 완성된 충부를 필수 표지로 요구하지 않습니다. 주수에 맞는 뇌 발달 구조를 기준으로 합니다.','소뇌 충부 발달과 주수를 함께 해석합니다. NF를 측정할 때는 적용 주수·프로토콜을 확인하며 NT와 구분합니다.','골화와 골반 내 진입으로 관찰이 제한될 수 있습니다. 접근 창을 바꿔도 안 보이는 구조는 제한으로 기록하고 NF를 후기 필수 지표로 요구하지 않습니다.'],
 cardiac:['작은 판막·혈관은 가시성에 한계가 있습니다. 도플러는 필요할 때 최소 출력·최단 시간으로 적용합니다.','사강면뿐 아니라 유출로와 대혈관의 연결도 확인하고 적절한 심장 주기의 cine를 저장합니다.','늑골 음영과 태위 때문에 관찰이 어려워질 수 있습니다. 이전 결과와 비교하되 현재 보이지 않는 구조를 정상으로 단정하지 않습니다.'],
 limbs:['작은 골화 중심과 손발을 확인하되 모든 손가락·발가락이 분리되어 보일 것을 요구하지 않습니다.','양측 사지를 관절에서 끝까지 추적하고 일시적 자세와 지속되는 이상을 구분합니다.','굴곡·밀집과 골화 음영이 증가하므로 각 사지를 구간별로 추적하고 제한된 부위를 기록합니다.'],
 face:['작은 얼굴 구조는 해상도에 제한이 있습니다. 보이지 않는 구조를 결손으로 단정하지 않습니다.','얼굴의 관상·축상·정중시상면을 서로 보완하여 단면 오류를 줄입니다.','얼굴과 자궁벽의 밀착·손의 가림 때문에 재관찰이 필요할 수 있습니다. 강한 압박으로 자세를 억지로 바꾸지 않습니다.'],
 abdomen:['장기 크기와 발달 단계가 후기와 다릅니다. 복벽 삽입부에서는 초기 생리적 중장 탈출의 시기를 고려합니다.','장기 위치와 서로의 관계를 확인하고 필요한 계측은 해당 표준 단면에서 시행합니다.','크기·충만 상태·태동에 따라 모양이 변할 수 있습니다. 이전 계측과 같은 방법을 사용하고 음영으로 누락된 부위를 기록합니다.'],
 maternal:['초기 태반 위치·경부 길이를 중기나 후기와 같은 의미로 해석하지 않습니다.','경부·내구와 태반 가장자리의 관계를 명확히 하고 적응증에 맞는 접근법을 사용합니다.','태반 위치의 추적 결과와 현재 적응증을 확인합니다. 후기 경부 변화에 중기 선별 기준을 그대로 적용하지 않습니다.'],
 early:['인증된 1분기 측정 프로토콜의 주수·CRL 범위와 영상 기준을 확인합니다.','초기 측정 기준을 중기에 그대로 대입하지 않습니다.','초기 측정 기준을 후기에 그대로 대입하지 않습니다.']
};
const groupFor=type=>type==='spine'?'spine':type==='genitalia'?'genitalia':['head','ventricle','earlybrain','cerebellum'].includes(type)?'brain':['heart','lvot','rvot','threev','threevpa','vessels','aoarch','ductarch','bicaval'].includes(type)?'cardiac':['femur','humerus','tibia','forearm','foot','hand'].includes(type)?'limbs':['face','orbit','facialprofile'].includes(type)?'face':['placenta','cervix'].includes(type)?'maternal':['profile','nt'].includes(type)?'early':'abdomen';
export function scanTipsFor(v){
 if(!tips[v.type])return null;
 const items=tips[v.type].map(t=>[...t]),trimester=v.trimester||2;
 if(v.type==='cerebellum'&&trimester===1){items[0]=['과도한 틸트 주의','초기 시상·후두와 표지를 기준으로 조금씩 조절합니다. CSP가 안 보인다는 이유로 더 기울이지 않습니다.'];items[2]=['압박·측정 구분','편안한 접촉을 유지하고 초기 후두와를 관찰합니다. 중기 NF 기준을 적용하거나 NT 측정을 이 단면으로 대신하지 않습니다.'];}
 items.push([`${trimester}분기에서 주의`,ageNotes[groupFor(v.type)][trimester-1]]);
 return {items,extraSources:v.type==='cerebellum'&&trimester===2?[['NF 촬영 각도·태위 연구 · Cho 2005','https://doi.org/10.1002/uog.1847']]:[]};
}
export function renderScanTips(v){const p=scanTipsFor(v);if(!p)return '';return `<section class="scan-tips" aria-label="영상 획득 시 주의해야 할 핵심 팁"><h4>영상 획득 시 주의해야 할 핵심 팁</h4><ul>${p.items.map(([title,text])=>`<li><strong>${title}</strong><p>${text}</p></li>`).join('')}</ul>${p.extraSources.map(([name,url])=>`<a class="scan-tip-source" href="${url}" target="_blank" rel="noopener">${name} ↗</a>`).join('')}</section>`;}
